class Solution {
    public String getPermutation(int n, int k) {
        List<Integer> nums = new java.util.ArrayList<>();
        int[] fact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
            nums.add(i);
        }
        k--;
        StringBuilder sb = new StringBuilder();
        for (int i = n; i > 0; i--) {
            int idx = k / fact[i - 1];
            sb.append(nums.remove(idx));
            k %= fact[i - 1];
        }
        return sb.toString();
    }
}

class Solution {
    public String getPermutation(int n, int k) {
        boolean[] used = new boolean[n + 1];
        int[] fact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
        }
        k--;
        StringBuilder sb = new StringBuilder();
        for (int i = n; i > 0; i--) {
            int idx = k / fact[i - 1];
            k %= fact[i - 1];
            int count = 0;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    if (count == idx) {
                        sb.append(j);
                        used[j] = true;
                        break;
                    }
                    count++;
                }
            }
        }
        return sb.toString();
    }
}
